window.CODE = Object.assign(window.CODE || {}, {"ch14/graph_agent.py":"\"\"\"The Chapter 9 agent loop, drawn as a graph: model -> tools -> model ... -> END.\n\nMessagesState has one key, \"messages\", with a REDUCER (add_messages) that appends new\nmessages instead of replacing the list. That is why nodes can return just the new message.\n\nRun:  python graph_agent.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nsys.path.insert(0, str(HERE.parent / \"ch13\"))\nfrom clinic_tools import SYSTEM, TOOLS  # noqa: E402  (the LangChain tools from Chapter 13)\nfrom langgraph.graph import START, MessagesState, StateGraph  # noqa: E402\nfrom langgraph.prebuilt import ToolNode, tools_condition  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\nmodel_with_tools = get_model().bind_tools(TOOLS)\n\n\ndef call_model(state: MessagesState) -> dict:\n    \"\"\"Reason: send the system prompt and the whole history to the model.\"\"\"\n    reply = model_with_tools.invoke([(\"system\", SYSTEM)] + state[\"messages\"])\n    return {\"messages\": [reply]}            # add_messages APPENDS this to the history\n\n\nbuilder = StateGraph(MessagesState)\nbuilder.add_node(\"model\", call_model)\nbuilder.add_node(\"tools\", ToolNode(TOOLS))           # Act: runs every tool call in the last message\nbuilder.add_edge(START, \"model\")\nbuilder.add_conditional_edges(\"model\", tools_condition)   # tool calls? -> \"tools\", otherwise -> END\nbuilder.add_edge(\"tools\", \"model\")                   # Observe: results go back to the model\ngraph = builder.compile()\n\nif __name__ == \"__main__\":\n    question = \"Book Dr Iyer on Wednesday for Ravi Kumar.\"\n    for step in graph.stream({\"messages\": [(\"user\", question)]}, stream_mode=\"updates\"):\n        for node, update in step.items():\n            m = update[\"messages\"][-1]\n            print(f\"[{node}] {m.tool_calls if getattr(m, 'tool_calls', None) else m.content}\")\n","ch14/graph_basics.py":"\"\"\"Your first LangGraph graph: a helpdesk router.\n\nState  = a dict every node can read; each node returns ONLY the keys it changes.\nNodes  = plain Python functions.\nEdges  = what runs next. A conditional edge is a function that picks the next node.\n\nRun:  python graph_basics.py\n\"\"\"\nimport sys\nfrom pathlib import Path\nfrom typing import Literal, TypedDict\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom langgraph.graph import END, START, StateGraph  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\nfrom pydantic import BaseModel  # noqa: E402\n\nEMERGENCY_WORDS = (\"chest pain\", \"can't breathe\", \"cannot breathe\", \"unconscious\", \"bleeding heavily\")\n\n\nclass State(TypedDict, total=False):\n    message: str\n    intent: str\n    reply: str\n    route: list[str]          # which nodes ran, for teaching\n\n\nclass Intent(BaseModel):\n    intent: Literal[\"schedule\", \"billing\", \"other\"]\n\n\nmodel = get_model()\nclassifier = model.with_structured_output(Intent)\n\n\n# ---------------------------------------------------------------- nodes: state in, partial update out\ndef safety_check(state: State) -> dict:\n    hit = any(w in state[\"message\"].lower() for w in EMERGENCY_WORDS)\n    return {\"intent\": \"emergency\" if hit else \"\", \"route\": [\"safety_check\"]}\n\n\ndef classify(state: State) -> dict:\n    result = classifier.invoke(f\"Classify this City Clinic message: {state['message']}\")\n    return {\"intent\": result.intent, \"route\": state[\"route\"] + [\"classify\"]}\n\n\ndef emergency(state: State) -> dict:\n    return {\"reply\": \"Please go to Emergency now or call 108.\", \"route\": state[\"route\"] + [\"emergency\"]}\n\n\ndef answer(state: State) -> dict:\n    text = model.invoke([(\"system\", f\"You are the City Clinic helpdesk. Topic: {state['intent']}. \"\n                                   \"One short sentence. No medical advice.\"),\n                         (\"user\", state[\"message\"])]).content\n    return {\"reply\": text, \"route\": state[\"route\"] + [\"answer\"]}\n\n\ndef handoff(state: State) -> dict:\n    return {\"reply\": \"I'll pass this to our front desk (1800-000-000).\", \"route\": state[\"route\"] + [\"handoff\"]}\n\n\n# ---------------------------------------------------------------- conditional edges: state in, node name out\ndef after_safety(state: State) -> Literal[\"emergency\", \"classify\"]:\n    return \"emergency\" if state[\"intent\"] == \"emergency\" else \"classify\"\n\n\ndef after_classify(state: State) -> Literal[\"answer\", \"handoff\"]:\n    return \"handoff\" if state[\"intent\"] == \"other\" else \"answer\"\n\n\n# ---------------------------------------------------------------- build the graph\nbuilder = StateGraph(State)\nbuilder.add_node(\"safety_check\", safety_check)\nbuilder.add_node(\"classify\", classify)\nbuilder.add_node(\"emergency\", emergency)\nbuilder.add_node(\"answer\", answer)\nbuilder.add_node(\"handoff\", handoff)\n\nbuilder.add_edge(START, \"safety_check\")\nbuilder.add_conditional_edges(\"safety_check\", after_safety)\nbuilder.add_conditional_edges(\"classify\", after_classify)\nbuilder.add_edge(\"emergency\", END)\nbuilder.add_edge(\"answer\", END)\nbuilder.add_edge(\"handoff\", END)\n\ngraph = builder.compile()\n\nif __name__ == \"__main__\":\n    for msg in [\"Which days does Dr Rao see patients?\", \"My mother has chest pain\", \"Can I bring my dog?\"]:\n        out = graph.invoke({\"message\": msg})\n        print(f\"{msg}\\n  path:  {' -> '.join(out['route'])}\\n  reply: {out['reply']}\\n\")\n    print(graph.get_graph().draw_mermaid())      # paste into mermaid.live to see the picture\n","ch14/graph_memory.py":"\"\"\"Conversation memory with a checkpointer, plus trimming so long chats stay affordable.\n\ncheckpointer + thread_id  -> the graph saves state after every step and reloads it next time\ntrim_messages             -> only the last N tokens of history are sent to the model\n\nRun:  python graph_memory.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom langchain_core.messages import trim_messages  # noqa: E402\nfrom langgraph.checkpoint.memory import InMemorySaver  # noqa: E402\nfrom langgraph.graph import START, MessagesState, StateGraph  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\nmodel = get_model()\nSYSTEM = \"You are the City Clinic helpdesk. OPD: Mon-Sat 9-1 and 4-7. Keep replies to one sentence.\"\n\n\ndef chat(state: MessagesState) -> dict:\n    recent = trim_messages(state[\"messages\"], max_tokens=300, strategy=\"last\",\n                           token_counter=\"approximate\", start_on=\"human\")   # never start mid-exchange\n    return {\"messages\": [model.invoke([(\"system\", SYSTEM)] + recent)]}\n\n\nbuilder = StateGraph(MessagesState)\nbuilder.add_node(\"chat\", chat)\nbuilder.add_edge(START, \"chat\")\ngraph = builder.compile(checkpointer=InMemorySaver())   # SqliteSaver / PostgresSaver in production\n\nif __name__ == \"__main__\":\n    asha = {\"configurable\": {\"thread_id\": \"asha\"}}\n    ravi = {\"configurable\": {\"thread_id\": \"ravi\"}}\n\n    for text in [\"Hi, I'm Asha. Is OPD open on Saturday?\", \"What was my name again?\"]:\n        out = graph.invoke({\"messages\": [(\"user\", text)]}, asha)    # only the NEW message is sent\n        print(f\"asha> {text}\\n  bot: {out['messages'][-1].content}\")\n\n    out = graph.invoke({\"messages\": [(\"user\", \"What was my name again?\")]}, ravi)\n    print(f\"ravi> What was my name again?\\n  bot: {out['messages'][-1].content}\")\n\n    state = graph.get_state(asha)\n    print(f\"\\nSaved for thread 'asha': {len(state.values['messages'])} messages\")\n    print(\"Checkpoints saved:\", len(list(graph.get_state_history(asha))))\n","ch14/graph_production.py":"\"\"\"Production habits for graphs: retry policies, step limits, friendly failures and streaming.\n\nRun:  python graph_production.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nsys.path.insert(0, str(HERE.parent / \"ch13\"))\nfrom clinic_tools import SYSTEM, TOOLS  # noqa: E402\nfrom langgraph.errors import GraphRecursionError  # noqa: E402\nfrom langgraph.graph import START, MessagesState, StateGraph  # noqa: E402\nfrom langgraph.prebuilt import ToolNode, tools_condition  # noqa: E402\nfrom langgraph.types import RetryPolicy  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\nmodel = get_model().bind_tools(TOOLS)\n\n\ndef call_model(state: MessagesState) -> dict:\n    return {\"messages\": [model.invoke([(\"system\", SYSTEM)] + state[\"messages\"])]}\n\n\nbuilder = StateGraph(MessagesState)\n# Retry this node up to 3 times with exponential backoff if it raises (timeouts, 5xx errors).\nbuilder.add_node(\"model\", call_model, retry_policy=RetryPolicy(max_attempts=3, initial_interval=1.0))\nbuilder.add_node(\"tools\", ToolNode(TOOLS, handle_tool_errors=True))   # tool exceptions -> messages\nbuilder.add_edge(START, \"model\")\nbuilder.add_conditional_edges(\"model\", tools_condition)\nbuilder.add_edge(\"tools\", \"model\")\ngraph = builder.compile()\n\n\ndef ask(question: str, max_steps: int = 10) -> str:\n    \"\"\"Run the graph with a step limit, and turn failures into a safe reply.\"\"\"\n    try:\n        out = graph.invoke({\"messages\": [(\"user\", question)]}, {\"recursion_limit\": max_steps})\n        return out[\"messages\"][-1].content\n    except GraphRecursionError:\n        # The agent needed more steps than allowed: stop, log it, and hand over.\n        return \"Sorry, I couldn't finish that. Our front desk can help: 1800-000-000.\"\n\n\nif __name__ == \"__main__\":\n    print(\"Normal:      \", ask(\"Which days does Dr Khan work?\"))\n    print(\"Step limit 2:\", ask(\"Which days does Dr Khan work?\", max_steps=2))\n\n    print(\"\\nstream_mode='values' (full state after each step):\")\n    for state in graph.stream({\"messages\": [(\"user\", \"Which days does Dr Khan work?\")]}, stream_mode=\"values\"):\n        print(f\"  {len(state['messages'])} messages, last from {state['messages'][-1].type}\")\n","ch14/langgraph.json":"{\n  \"dependencies\": [\".\"],\n  \"graphs\": {\n    \"helpdesk_router\": \"./graph_basics.py:graph\",\n    \"helpdesk_agent\": \"./graph_agent.py:graph\"\n  },\n  \"env\": \"../.env\"\n}\n","ch14/test_graph.py":"\"\"\"Nodes are plain functions, so you can unit-test them without a model or a graph.\n\nRun:  pytest test_graph.py\n\"\"\"\nimport os\n\n# Building the model object needs a key, but these tests never call the model.\nos.environ.setdefault(\"OPENAI_API_KEY\", \"test-key-not-used\")\nos.environ.setdefault(\"ANTHROPIC_API_KEY\", \"test-key-not-used\")\nimport graph_basics as g  # noqa: E402\n\n\ndef test_emergency_words_skip_the_model():\n    assert g.safety_check({\"message\": \"My father has CHEST PAIN\"})[\"intent\"] == \"emergency\"\n\n\ndef test_normal_message_goes_to_classifier():\n    state = {\"message\": \"OPD timings?\", **g.safety_check({\"message\": \"OPD timings?\"})}\n    assert g.after_safety(state) == \"classify\"\n\n\ndef test_unknown_intent_is_handed_over():\n    assert g.after_classify({\"intent\": \"other\"}) == \"handoff\"\n    assert g.after_classify({\"intent\": \"billing\"}) == \"answer\"\n","common/lc_models.py":"\"\"\"One place to create LangChain chat models and embeddings for every Part C chapter.\n\nLangChain hides the provider differences, so switching OpenAI <-> Anthropic is one line:\n\n    init_chat_model(\"openai:gpt-4.1-mini\")     or     init_chat_model(\"anthropic:claude-haiku-5-5\")\n\nThis helper reads the same .env settings as llm.py (PROVIDER, OPENAI_MODEL, ANTHROPIC_MODEL).\n\n    from lc_models import get_model, get_embeddings\n    model = get_model()                  # a LangChain chat model for your PROVIDER\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\nfrom langchain.chat_models import init_chat_model\nfrom langchain_core.embeddings import Embeddings\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\n\n\ndef get_model(provider: str | None = None, temperature: float = 0, **kwargs):\n    \"\"\"A chat model with sensible production defaults: a timeout and automatic retries.\"\"\"\n    provider = provider or PROVIDER\n    return init_chat_model(f\"{provider}:{MODELS[provider]}\", temperature=temperature,\n                           timeout=float(os.getenv(\"LLM_TIMEOUT\", \"30\")),\n                           max_retries=int(os.getenv(\"LLM_RETRIES\", \"2\")), **kwargs)\n\n\nclass CourseEmbeddings(Embeddings):\n    \"\"\"Wraps llm.embed() (Chapter 6) so LangChain vector stores can use it.\n    EMBEDDINGS=openai uses text-embedding-3-small; EMBEDDINGS=local uses a free local model.\"\"\"\n\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\n        from llm import embed\n        return embed(texts)\n\n    def embed_query(self, text: str) -> list[float]:\n        return self.embed_documents([text])[0]\n\n\ndef get_embeddings() -> Embeddings:\n    return CourseEmbeddings()\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
